import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup with case differences
const input = ['Apple', 'banana', 'APPLE', 'Banana', 'cherry', 'apple'];
const out = uniqueStrings(input);
console.log('Result:', JSON.stringify(out));
console.assert(JSON.stringify(out) === JSON.stringify(['Apple', 'banana', 'cherry']), 'FAIL basic');

// Input not mutated
console.assert(JSON.stringify(input) === JSON.stringify(['Apple', 'banana', 'APPLE', 'Banana', 'cherry', 'apple']), 'FAIL mutation');

// Whitespace preserved (not trimmed)
const ws = uniqueStrings(['  hi', 'hi', '  hi']);
console.log('Whitespace:', JSON.stringify(ws));
console.assert(JSON.stringify(ws) === JSON.stringify(['  hi', 'hi']), 'FAIL whitespace');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === JSON.stringify([]), 'FAIL empty');

// Original spelling preserved
const spell = uniqueStrings(['Foo', 'FOO', 'foo', 'Bar']);
console.log('Spelling:', JSON.stringify(spell));
console.assert(JSON.stringify(spell) === JSON.stringify(['Foo', 'Bar']), 'FAIL spelling');

// Non-ASCII unaffected by toLowerCase key (still dedups exact matches)
const unicode = uniqueStrings(['café', 'CAFÉ', 'café']);
console.log('Unicode:', JSON.stringify(unicode));
console.assert(JSON.stringify(unicode) === JSON.stringify(['café', 'CAFÉ']), 'FAIL unicode');

console.log('All checks passed.');
"

